-- Meu Treino v12: banco real de exercícios + compatibilidade com o app.
-- Execute este arquivo UMA vez no SQL Editor do Supabase. Pode ser reexecutado com segurança.

alter table public.exercises add column if not exists slug text;
alter table public.exercises add column if not exists description text;
alter table public.exercises add column if not exists muscle_group text;
alter table public.exercises add column if not exists secondary_muscles text;
alter table public.exercises add column if not exists movement_type text;
alter table public.exercises add column if not exists difficulty text;
alter table public.exercises add column if not exists exercise_type text;
alter table public.exercises add column if not exists instructions text;
alter table public.exercises add column if not exists image_url text;
alter table public.exercises add column if not exists video_url text;
alter table public.exercises add column if not exists active boolean not null default true;
alter table public.exercises add column if not exists is_official boolean not null default false;

create unique index if not exists exercises_official_slug_uq on public.exercises(slug) where is_official=true;
create unique index if not exists exercise_videos_user_exercise_uq on public.exercise_videos(user_id,exercise_id);

update public.exercises set muscle_group=coalesce(muscle_group,group_name), active=coalesce(active,true);


drop policy if exists "official_exercises_read" on public.exercises;
create policy "official_exercises_read" on public.exercises for select using (is_official=true or user_id=auth.uid());

grant select on public.exercises to anon, authenticated;
-- Corrige as políticas de propriedade sem depender de uma coluna id inexistente em user_snapshots.
do $$ declare t text; begin
for t in select unnest(array['user_snapshots','exercises','exercise_videos','workouts','workout_sessions','weight_records','cardio_records','photos','favorites','ai_conversations','ai_generated_workouts','trash','audit_logs','settings']) loop
  execute format('drop policy if exists "owner_select" on public.%I',t);
  execute format('drop policy if exists "owner_insert" on public.%I',t);
  execute format('drop policy if exists "owner_update" on public.%I',t);
  execute format('drop policy if exists "owner_delete" on public.%I',t);
  execute format('create policy "owner_select" on public.%I for select using (user_id = auth.uid())',t);
  execute format('create policy "owner_insert" on public.%I for insert with check (user_id = auth.uid())',t);
  execute format('create policy "owner_update" on public.%I for update using (user_id = auth.uid()) with check (user_id = auth.uid())',t);
  execute format('create policy "owner_delete" on public.%I for delete using (user_id = auth.uid())',t);
end loop;
end $$;

drop policy if exists "owner_select" on public.profiles;
drop policy if exists "owner_insert" on public.profiles;
drop policy if exists "owner_update" on public.profiles;
drop policy if exists "owner_delete" on public.profiles;
create policy "owner_select" on public.profiles for select using (id = auth.uid());
create policy "owner_insert" on public.profiles for insert with check (id = auth.uid());
create policy "owner_update" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy "owner_delete" on public.profiles for delete using (id = auth.uid());
